function pointOnPolyline(pts, t) {
  var total = pathLength(pts);
  var target = ((t % 1) + 1) % 1 * total;
  var acc = 0;
  for (var i = 1; i < pts.length; i++) {
    var ax = pts[i - 1][0], ay = pts[i - 1][1], bx = pts[i][0], by = pts[i][1];
    var dx = bx - ax, dy = by - ay;
    var seg = Math.sqrt(dx * dx + dy * dy);
    if (acc + seg >= target) {
      var u = (target - acc) / seg;
      return [ax + dx * u, ay + dy * u];
    }
    acc += seg;
  }
  return pts[pts.length - 1];
}

